func repair(q: LinkedList<Int64>, mark: ?LinkedListNode<Int64>, t: Int64): Int64 {
    var result: Int64 = 0
    var node: ?LinkedListNode<Int64> = None
    match (mark) {
        case Some(m) => node = m.next
        case None => return result
    }
    var add: Bool = true
    while (true) {
        match (node) {
            case Some(n) =>
                let v = n.value
                if (v == t) {
                    break
                }
                if (add) {
                    result += v
                } else {
                    result -= v
                }
                add = !add
                node = n.next
            case None => break
        }
    }
    return result
}

main() {
