func repair(q: LinkedList<Int64>, offset: Int64, t: Int64): Int64 {
    if (q.isEmpty()) {
        return 0
    }
    if (offset < 0 || offset >= q.size) {
        return 0
    }
    let place = q.nodeAt(offset)
    match (place) {
        case Some(node) =>
            var count: Int64 = 0
            var cur = node.prev
            while (count < 2) {
                match (cur) {
                    case Some(n) =>
                        if (n.value % 2 != 0) {
                            n.value = n.value + t
                            count = count + 1
                        }
                        cur = n.prev
                    case None =>
                        break
                }
            }
            return count
        case None =>
            return 0
    }
}

main() {
    let q0 = LinkedList<Int64>([5, -2, -2, 6, 3])
    let r0 = repair(q0, 3, 2)
    println(r0 == 1 && q0.toArray() == [7, -2, -2, 6, 3])
    let q1 = LinkedList<Int64>([3, 1, 4, 4, -3])
    let r1 = repair(q1, 1, 4)
    println(r1 == 1 && q1.toArray() == [7, 1, 4, 4, -3])
}
