            var it = q.forward(node)
            // forward 从 mark 本身开始，先跳过标记本身
            if (it.next().isSome()) {
                while (true) {
                    match (it.next()) {
                        case Some(v) =>
                            if (v == t) {
                                break
                            }
                            if (v < 0) {
                                // 需要修改节点值；通过重新定位节点实现
