                let arr = q.toArray()
                var i = offset + 1
                while (i < arr.size) {
                    if (arr[i] == t) {
                        break
                    }
                    if (arr[i] < 0) {
                        arr[i] = -arr[i]
                    }
                    i++
                }
                q.clear()
